def solve_rush_hour():
    initial_cars = {
        'AA': ((2, 1), (2, 2), 'H'),
        'BBB': ((0, 0), (0, 1), (0, 2), 'H'),
        'CC': ((0, 3), (0, 4), 'H'),
        'DD': ((1, 0), (1, 1), 'H'),
        'EE': ((3, 3), (3, 4), 'H'),
        'FF': ((4, 0), (4, 1), 'H'),
        'GG': ((5, 1), (5, 2), 'H'),
        'H': ((2, 0), (3, 0), 'V'),
        'I': ((3, 2), (4, 2), 'V'),
        'J': ((4, 3), (5, 3), 'V'),
        'K': ((1, 4), (2, 4), 'V'),
        'L': ((0, 5), (1, 5), 'V'),
        'M': ((2, 5), (3, 5), 'V'),
    }
    walls = {(1, 3), (5, 0)}

    def get_occupied(cars):
        occ = {w: 'x' for w in walls}
        for name, info in cars.items():
            for r, c in info[:-1]:
                occ[(r, c)] = name
        return occ

    queue = collections.deque([(initial_cars, [])])
    visited = {tuple(sorted((n, i) for n, i in initial_cars.items()))}

    while queue:
        curr_cars, path = queue.popleft()
        if curr_cars['AA'][1] == (2, 5):
            return path

        occ = get_occupied(curr_cars)
        for name, info in curr_cars.items():
            coords = info[:-1]
            orient = info[-1]
            if orient == 'H':
                r, c_max = coords[-1]
                for d in range(1, 6):
                    if c_max + d < 6 and (r, c_max + d) not in occ:
                        new_coords = tuple((r, c + d) for r, c in coords) + ('H',)
                        new_cars = curr_cars.copy()
                        new_cars[name] = new_coords
                        state = tuple(sorted((n, i) for n, i in new_cars.items()))
                        if state not in visited:
                            visited.add(state)
                            queue.append((new_cars, path + [f"{name}+{d}"]))
                    else: break
                r, c_min = coords[0]
                for d in range(1, 6):
                    if c_min - d >= 0 and (r, c_min - d) not in occ:
                        new_coords = tuple((r, c - d) for r, c in coords) + ('H',)
                        new_cars = curr_cars.copy()
                        new_cars[name] = new_coords
                        state = tuple(sorted((n, i) for n, i in new_cars.items()))
                        if state not in visited:
                            visited.add(state)
                            queue.append((new_cars, path + [f"{name}-{d}"]))
                    else: break
            else:
                r_max, c = coords[-1]
                for d in range(1, 6):
                    if r_max + d < 6 and (r_max + d, c) not in occ:
                        new_coords = tuple((r + d, c) for r, c in coords) + ('V',)
                        new_cars = curr_cars.copy()
                        new_cars[name] = new_coords
                        state = tuple(sorted((n, i) for n, i in new_cars.items()))
                        if state not in visited:
                            visited.add(state)
                            queue.append((new_cars, path + [f"{name}+{d}"]))
                    else: break
                r_min, c = coords[0]
                for d in range(1, 6):
                    if r_min - d >= 0 and (r_min - d, c) not in occ:
                        new_coords = tuple((r - d, c) for r, c in coords) + ('V',)
                        new_cars = curr_cars.copy()
                        new_cars[name] = new_coords
                        state = tuple(sorted((n, i) for n, i in new_cars.items()))
                        if state not in visited:
                            visited.add(state)
                            queue.append((new_cars, path + [f"{name}-{d}"]))
                    else: break
    return None

sol = solve_rush_hour()
print(' '.join(sol) if sol else 'No solution')"}

